// src/pages/Home.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';

const Home = () => {
  const [username, setUsername] = useState('');
  const [roomCode, setRoomCode] = useState('');
  const [isCreating, setIsCreating] = useState(false);
  const [isJoining, setIsJoining] = useState(false);
  const navigate = useNavigate();

  const generateRoomId = () => {
    const prefixes = ['PARTY', 'WATCH', 'VIDEO', 'MOVIE', 'FUN', 'CHILL'];
    const prefix = prefixes[Math.floor(Math.random() * prefixes.length)];
    const randomNum = Math.floor(Math.random() * 10000);
    const randomChars = Math.random().toString(36).substr(2, 4).toUpperCase();
    return `${prefix}-${randomNum}-${randomChars}`;
  };

  const generateUserId = () => {
    return 'user_' + Date.now() + '_' + Math.random().toString(36).substr(2, 8);
  };

  const createRoom = () => {
    if (!username.trim()) {
      alert('✨ Please enter your name!');
      return;
    }

    setIsCreating(true);
    
    setTimeout(() => {
      const newRoomId = generateRoomId();
      const userId = generateUserId();
      
      localStorage.setItem('userId', userId);
      localStorage.setItem('username', username);
      localStorage.setItem('role', 'HOST');
      localStorage.setItem('useMockMode', 'true');
      
      alert(`🎉 Room Created!\n\nRoom Code: ${newRoomId}\n\nShare this code to invite friends!`);
      
      navigate(`/room/${newRoomId}`);
      setIsCreating(false);
    }, 500);
  };

  const joinRoom = () => {
    if (!username.trim()) {
      alert('✨ Please enter your name!');
      return;
    }
    if (!roomCode.trim()) {
      alert('🔑 Please enter a room code!');
      return;
    }

    setIsJoining(true);
    
    setTimeout(() => {
      const userId = generateUserId();
      
      localStorage.setItem('userId', userId);
      localStorage.setItem('username', username);
      localStorage.setItem('role', 'PARTICIPANT');
      localStorage.setItem('useMockMode', 'true');
      
      alert(`🎉 Joined Room: ${roomCode.toUpperCase()}!\n\nYou joined as PARTICIPANT!`);
      
      navigate(`/room/${roomCode.toUpperCase()}`);
      setIsJoining(false);
    }, 500);
  };

  return (
    <div className="home-container">
      <div className="home-card fade-in-up">
        <div style={{ 
          background: '#4caf50', 
          padding: '4px 12px', 
          borderRadius: '20px', 
          display: 'inline-block',
          marginBottom: '15px',
          fontSize: '12px',
          fontWeight: 'bold',
          color: 'white'
        }}>
          🎮 TEST MODE ACTIVE
        </div>
        
        <h1>🎬 YouTube Watch Party</h1>
        <p>Watch YouTube videos together with friends in real-time!</p>
        
        <div className="input-group">
          <input
            type="text"
            placeholder="✨ Enter your name"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
        </div>

        <div className="action-buttons">
          <button 
            className="btn btn-primary"
            onClick={createRoom}
            disabled={isCreating}
          >
            {isCreating ? 'Creating...' : '✨ Create New Party'}
          </button>
          
          <div className="divider">OR</div>
          
          <div className="join-section">
            <input
              type="text"
              placeholder="🔑 Enter room code"
              value={roomCode}
              onChange={(e) => setRoomCode(e.target.value.toUpperCase())}
            />
            <button 
              className="btn btn-primary"
              onClick={joinRoom}
              disabled={isJoining}
            >
              {isJoining ? 'Joining...' : '🚪 Join Party'}
            </button>
          </div>
        </div>

        <div className="features">
          <div className="feature-badge">Real-time Sync</div>
          <div className="feature-badge">Role-based Access</div>
          <div className="feature-badge">Live Chat</div>
          <div className="feature-badge">YouTube Integration</div>
        </div>

        <div style={{ marginTop: '20px', padding: '10px', background: '#f0f0f0', borderRadius: '10px', fontSize: '12px' }}>
          <strong>📖 How to Test Two-Way Sync:</strong><br/>
          1. Open this app in TWO browser tabs<br/>
          2. Tab 1: Enter name, click "Create New Party"<br/>
          3. Copy the Room Code shown<br/>
          4. Tab 2: Enter different name, paste Room Code, click "Join Party"<br/>
          5. Watch real-time sync between tabs! 🎉
        </div>
      </div>
    </div>
  );
};

export default Home;
